import{_ as o,o as r,c as d,a2 as s}from"./chunks/framework.DGvnA5EY.js";const a="/workbuddy-guide/assets/01-remote-control-flow.Dj2hQj3c.png",n="/workbuddy-guide/assets/02-official-assistant-sidebar.CelZeSps.png",e="/workbuddy-guide/assets/03-official-assistant-settings-entry.m1V5GY4g.png",i="/workbuddy-guide/assets/04-official-weixin-config.B3o7ZTse.png",p="/workbuddy-guide/assets/05-official-weixin-scan.B4pImZpI.png",l="/workbuddy-guide/assets/06-official-weixin-connected.BsCR3lH2.png",g="/workbuddy-guide/assets/07-official-miniprogram-sync.Btuye0hY.png",u="/workbuddy-guide/assets/08-phone-miniapp-view.DoRqCGME.png",f=JSON.parse('{"title":"第 8 章 接入小程序与 IM 助理","description":"> 内容来源：WorkBuddy 官方指南 · 助理（远程任务）（非官方整理，© 本指南作者，保留所有权利） 前七章，你的每一步操作都发生在电脑前。这一章解决一个现实问题：人不在电脑前，活儿怎么办？","frontmatter":{"title":"第 8 章 接入小程序与 IM 助理"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 8 章 接入小程序与 IM 助理/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 8 章 接入小程序与 IM 助理/index.md","lastUpdated":1791629861000}'),m={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 8 章 接入小程序与 IM 助理/index.md"};function c(h,t,k,b,y,q){return r(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="第-8-章-接入小程序与-im-助理" tabindex="-1">第 8 章 接入小程序与 IM 助理 <a class="header-anchor" href="#第-8-章-接入小程序与-im-助理" aria-label="Permalink to &quot;第 8 章 接入小程序与 IM 助理&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南 · 助理（远程任务）（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>前七章，你的每一步操作都发生在电脑前。这一章解决一个现实问题：<strong>人不在电脑前，活儿怎么办？</strong></p><p>WorkBuddy 给了两个答案：</p><ol><li><strong>IM 助理</strong>——在手机上的微信、QQ、飞书里发条消息，远程遥控电脑上的 WorkBuddy 干活；</li><li><strong>小程序</strong>——电脑上生成的文档、表格、PPT 自动同步到手机上的 WorkBuddy 小程序，随时看、随时转。</li></ol><p>一个管&quot;派活&quot;，一个管&quot;收货&quot;。配齐这两样，你的 AI 工作台就真正随身携带了。</p><h2 id="一、im-助理-给-workbuddy-配一个-遥控器" tabindex="-1">一、IM 助理：给 WorkBuddy 配一个&quot;遥控器&quot; <a class="header-anchor" href="#一、im-助理-给-workbuddy-配一个-遥控器" aria-label="Permalink to &quot;一、IM 助理：给 WorkBuddy 配一个&quot;遥控器&quot;&quot;">​</a></h2><p>官方文档的比喻很直白：助理就像一个<strong>遥控器</strong>——在手机上发一条消息，电脑上的 WorkBuddy 就会自动执行任务，执行完成后，结果会回复到你的手机上。</p><p><img src="'+a+'" alt="手机发指令、小黑遥控电脑执行、结果传回手机" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解远程控制的过程，与实际软件界面无关。</em></p><p>支持的平台不少，先看清楚再选：</p><table tabindex="0"><thead><tr><th>平台</th><th>特点</th><th>适合谁</th></tr></thead><tbody><tr><td><strong>微信助理</strong>（推荐）</td><td>扫码即连，配置最简单</td><td>大多数个人用户</td></tr><tr><td>微信客服号</td><td>注册微信客服号收发消息</td><td>有客服/公众号场景</td></tr><tr><td>企微助理</td><td>在企业微信群 @机器人 下任务</td><td>团队协作</td></tr><tr><td>QQ 机器人</td><td>注册 QQ 机器人接入</td><td>QQ 重度用户</td></tr><tr><td>飞书</td><td>注册飞书应用接入</td><td>飞书办公团队</td></tr><tr><td>钉钉机器人</td><td>注册钉钉机器人接入</td><td>钉钉办公团队</td></tr></tbody></table><p>第一次接入，无脑选<strong>微信助理</strong>，本章第三节就用它做示范。</p><p><strong>远程任务和普通任务的区别</strong>，官方给了一组对比，值得看一眼：</p><table tabindex="0"><thead><tr><th>对比项</th><th>普通任务</th><th>助理</th></tr></thead><tbody><tr><td>工作目录</td><td>自由指定</td><td>固定使用<strong>助理</strong>专属文件夹</td></tr><tr><td>新建对话</td><td>支持多个并行任务</td><td>仅一个会话，所有远程指令集中处理</td></tr><tr><td>上下文管理</td><td>可清空历史重新开始</td><td>保留完整对话历史，不可清空</td></tr></tbody></table><p>官方建议原话：<strong>本地操作优先使用主界面的普通任务；需要远程触发或统一查看记录时，再使用助理。</strong></p><h2 id="二、找到助理入口" tabindex="-1">二、找到助理入口 <a class="header-anchor" href="#二、找到助理入口" aria-label="Permalink to &quot;二、找到助理入口&quot;">​</a></h2><p>在主界面左侧导航栏，「新建任务」下面就是**「助理」**。</p><p><img src="'+n+'" alt="左侧导航栏中的「助理」入口，红框圈出" loading="lazy"></p><p><em>此图片来自官方。</em></p><p>点进去就是助理页面。之后所有远程任务的完整执行记录——思考过程、操作步骤、生成文件和最终结果——都在这里看。</p><h2 id="三、第一次接入-微信助理扫码绑定" tabindex="-1">三、第一次接入：微信助理扫码绑定 <a class="header-anchor" href="#三、第一次接入-微信助理扫码绑定" aria-label="Permalink to &quot;三、第一次接入：微信助理扫码绑定&quot;">​</a></h2><p>整个流程 4 步，跟着截图点就行。</p><p><strong>第 1 步</strong>：点侧边栏「助理」右侧的<strong>齿轮图标</strong>，打开助理设置。</p><p><img src="'+e+'" alt="「助理」右侧的设置齿轮按钮" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>第 2 步</strong>：在助理设置页找到「微信助理集成」（带推荐标），点右侧**「配置」**按钮，页面会生成一个二维码。</p><p><img src="'+i+'" alt="点「微信助理集成」右侧的「配置」，生成二维码" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>第 3 步</strong>：<strong>打开手机微信扫一扫</strong>，扫这个二维码。</p><p><img src="'+p+'" alt="打开微信扫描此二维码" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>第 4 步</strong>：扫码成功后，卡片上会亮起**「已连接」**，同时多出一个「解绑」按钮——说明绑定完成。</p><p><img src="'+l+'" alt="微信助理集成显示「已连接」" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>新手必踩的坑：二维码过期。</strong> 二维码是临时生成的，页面上标着倒计时（设置页 15 分钟，扫码页甚至只有 56 秒）。过期了不要慌，回到助理设置重新点一次「配置」，生成新码再扫即可。</p><p>另外两个前置条件别忽略：<strong>电脑必须开机并运行着 WorkBuddy</strong>，网络要正常。电脑关机了，手机端发什么都不会有回应。</p><h2 id="四、任务产物自动同步到小程序" tabindex="-1">四、任务产物自动同步到小程序 <a class="header-anchor" href="#四、任务产物自动同步到小程序" aria-label="Permalink to &quot;四、任务产物自动同步到小程序&quot;">​</a></h2><p>派活解决了，再解决收货。</p><p>还是在<strong>助理设置</strong>页的最顶部，有一个开关：<strong>「任务产物自动同步到小程序」</strong>。把它打开。</p><p><img src="'+g+'" alt="助理设置顶部的「任务产物自动同步到小程序」开关" loading="lazy"></p><p><em>此图片来自官方。</em></p><p>开启后，WorkBuddy 每次在电脑端完成任务，生成的报告、文案、表格、PPT 都会自动推送到你的 WorkBuddy 小程序：</p><ol><li>打开微信，<strong>下拉聊天列表</strong>进入小程序面板，点开 workbuddy 小程序；</li><li>产物按时间排列，可以浏览文档、复制文案、查看图表；</li><li>支持一键转发给微信好友或群聊，也能保存到手机本地；</li><li>仅同一账号可见——系统会校验手机和电脑是同一个 WorkBuddy 账号，不用担心隐私串门。</li></ol><p><img src="'+u+'" alt="电脑产物自动同步进手机小程序，随时查看" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解小程序同步的过程，与实际软件界面无关。</em></p><p>这个能力在第 10 章的自动化任务里还会再次出现：创建定时任务时可以勾选「推送到小程序」，任务结果自动送进手机。</p><h2 id="五、解绑与安全边界" tabindex="-1">五、解绑与安全边界 <a class="header-anchor" href="#五、解绑与安全边界" aria-label="Permalink to &quot;五、解绑与安全边界&quot;">​</a></h2><p>不想用了，或者要换号：</p><ol><li>打开 <strong>设置 → 助理设置</strong>；</li><li>在列表里找到目标平台，点卡片右侧的**「解绑」**。</li></ol><p>解绑后：该平台账号不再能向这台 WorkBuddy 发指令，接入配置从本地删除；但已执行任务的历史记录保留在本地，其他已绑定平台不受影响。平台侧的机器人还在，只是消息没人接了。</p><p><strong>安全边界</strong>（官方明确写的三条）：</p><ul><li><strong>绑定身份</strong>：助理设置中配置关联账号，支持灵活换绑；</li><li><strong>来源校验</strong>：每一条远程指令都经过多层来源校验，不是谁都能指挥你的电脑；</li><li><strong>高风险确认</strong>：涉及文件删除、系统配置修改、批准命令执行等操作，需确认后才会执行。</li></ul><p>所以&quot;手机遥控电脑&quot;并不等于&quot;裸奔&quot;，这三层保险默认就在工作。</p><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 打开 设置 → 助理设置，认出六张平台集成卡片</li><li>[ ] 完成微信助理扫码绑定，看到「已连接」</li><li>[ ] 在手机上给 WorkBuddy 发一条远程任务，等结果回微信</li><li>[ ] 打开「任务产物自动同步到小程序」，在手机小程序里找到电脑端刚生成的产物</li><li>[ ] （可选）走一遍「解绑」流程，确认自己会随时取消绑定</li></ul><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>IM</strong>：Instant Messaging（即时通讯）的缩写，就是微信、QQ、飞书这类聊天软件。</p><p><strong>助理</strong>：WorkBuddy 的远程控制功能。你手机发消息，电脑执行，结果回手机。</p><p><strong>绑定</strong>：把你的聊天账号和电脑上的 WorkBuddy 关联起来。之后这个账号发的消息会被当成指令。</p><p><strong>二维码</strong>：一张方形图案，用手机扫一下就能完成配对，不用手动输账号密码。</p><p><strong>小程序</strong>：微信里不用下载 App 就能用的轻量应用。这里指 WorkBuddy 官方小程序，用来在手机上看产物。</p><p><strong>上下文</strong>：AI 记住的之前对话内容。助理会完整保留对话历史，不可清空，越用越&quot;懂你&quot;。</p><p><strong>解绑</strong>：解除绑定。之后该账号发的消息不再被 WorkBuddy 接收。</p></blockquote><hr><p><em>下一篇：第 9 章 如何接入外部 API——给 WorkBuddy 接上你自己的&quot;外脑&quot;。</em></p><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>',61)])])}const B=o(m,[["render",c]]);export{f as __pageData,B as default};
